// Generated by seans-mfe-tool. Do not edit — regenerated on every `remote:generate`.
//
// The wasm-bindgen exports the remote entry calls (ADR-100, ADR-101).
//
// One MFE instance per page, as in the web lane, driven through the SAME
// platform contract the native crate renders. `mount` runs `load` when the
// instance is not ready, then `render` for the capability — state guard,
// transitions and manifest hooks included — and only then asks the
// capability's developer-owned `render` to draw into the slot. `capability`
// runs any of the ten by name, which is what the remote entry's `mfe` object
// calls, so a host drives this MFE exactly as it drives a TypeScript one.
//
// The browser supplies what a native host would inject (ADR-101):
//   transport      — `fetch`, so `query` and the BFF provider reach the network
//   control_plane  — the shell's per-slot daemon channel (ADR-057), handed over
//                    through `mfe.attachControlPlane`
//   telemetry      — a host function, through `mfe.attachTelemetry`

use std::cell::RefCell;
use std::rc::Rc;
use std::sync::Arc;

use js_sys::{Function, Promise, Reflect, Uint8Array, JSON};
use wasm_bindgen::prelude::*;
use wasm_bindgen::JsCast;
use wasm_bindgen_futures::JsFuture;
use web_sys::Element;

use meridian_crew_services::{
    BoxFuture, HttpRequest, HttpResponse, MfeContext, MfeControlPlaneClient, MfeDependencies, MfeError,
    MfeLifecycleState, MfeTelemetry, MfeTelemetryEvent, MfeTransport, NativeMfe, MeridianCrewServicesMfe,
};

fn js_error(error: JsValue) -> MfeError {
    MfeError::Transport { message: error.as_string().unwrap_or_else(|| format!("{:?}", error)), status: None }
}

/// `MfeTransport` over the browser's `fetch`.
struct FetchTransport;

impl MfeTransport for FetchTransport {
    fn post(&self, request: HttpRequest) -> BoxFuture<'_, Result<HttpResponse, MfeError>> {
        Box::pin(async move {
            let window = web_sys::window().ok_or_else(|| js_error(JsValue::from_str("no window")))?;
            let headers = web_sys::Headers::new().map_err(js_error)?;
            for (name, value) in &request.headers {
                headers.set(name, value).map_err(js_error)?;
            }
            let init = web_sys::RequestInit::new();
            init.set_method("POST");
            init.set_headers(&headers);
            init.set_body(&Uint8Array::from(request.body.as_slice()));
            let req = web_sys::Request::new_with_str_and_init(&request.url, &init).map_err(js_error)?;
            let response: web_sys::Response = JsFuture::from(window.fetch_with_request(&req))
                .await
                .map_err(js_error)?
                .dyn_into()
                .map_err(js_error)?;
            let status = response.status();
            let buffer = JsFuture::from(response.array_buffer().map_err(js_error)?).await.map_err(js_error)?;
            Ok(HttpResponse { status, body: Uint8Array::new(&buffer).to_vec() })
        })
    }
}

thread_local! {
    static CHANNEL: RefCell<Option<JsValue>> = const { RefCell::new(None) };
    static TELEMETRY: RefCell<Option<Function>> = const { RefCell::new(None) };
}

/// The shell's daemon channel (ADR-057) as an `MfeControlPlaneClient` — the
/// same two members `BaseRemoteMFE` calls on `deps.wsClient`.
struct HostChannel;

impl MfeControlPlaneClient for HostChannel {
    fn connected(&self) -> bool {
        CHANNEL.with(|c| {
            c.borrow()
                .as_ref()
                .and_then(|channel| Reflect::get(channel, &JsValue::from_str("connected")).ok())
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        })
    }

    fn mutation<'a>(&'a self, query: &'a str, variables: serde_json::Value, timeout_ms: u64) -> BoxFuture<'a, Result<bool, MfeError>> {
        Box::pin(async move {
            let channel = CHANNEL
                .with(|c| c.borrow().clone())
                .ok_or_else(|| js_error(JsValue::from_str("no daemon channel attached")))?;
            let mutation: Function = Reflect::get(&channel, &JsValue::from_str("mutation"))
                .map_err(js_error)?
                .dyn_into()
                .map_err(js_error)?;
            let vars = JSON::parse(&variables.to_string()).map_err(js_error)?;
            let promise: Promise = mutation
                .call3(&channel, &JsValue::from_str(query), &vars, &JsValue::from_f64(timeout_ms as f64))
                .map_err(js_error)?
                .dyn_into()
                .map_err(js_error)?;
            Ok(JsFuture::from(promise).await.map_err(js_error)?.as_bool().unwrap_or(false))
        })
    }
}

/// A host telemetry function, called with each event as a plain object.
struct HostTelemetry;

impl MfeTelemetry for HostTelemetry {
    fn emit(&self, event: MfeTelemetryEvent) {
        TELEMETRY.with(|t| {
            if let (Some(sink), Ok(text)) = (t.borrow().as_ref(), serde_json::to_string(&event)) {
                if let Ok(value) = JSON::parse(&text) {
                    let _ = sink.call1(&JsValue::NULL, &value);
                }
            }
        });
    }

    fn is_active(&self) -> bool {
        TELEMETRY.with(|t| t.borrow().is_some())
    }
}

fn deps() -> MfeDependencies {
    MfeDependencies {
        transport: Some(Arc::new(FetchTransport)),
        control_plane: Some(Arc::new(HostChannel)),
        telemetry: Some(Arc::new(HostTelemetry)),
        ..MfeDependencies::default()
    }
}

thread_local! {
    // The BFF-backed provider, over `fetch` (ADR-101).
    static MFE: Rc<MeridianCrewServicesMfe> = Rc::new(MeridianCrewServicesMfe::with_transport(Arc::new(FetchTransport), deps()));
}

/// This page's MFE instance — for a capability's own `render` to query, emit
/// or push control-plane state through.
pub fn mfe() -> Rc<MeridianCrewServicesMfe> {
    MFE.with(Rc::clone)
}

fn to_js(error: MfeError) -> JsValue {
    JsValue::from_str(&error.to_string())
}

/// Hand over the shell's daemon channel (ADR-057).
#[wasm_bindgen]
pub fn attach_control_plane(channel: JsValue) {
    CHANNEL.with(|c| *c.borrow_mut() = Some(channel));
}

/// Hand over a telemetry function; `emit` reports `emitted: false` until one is.
#[wasm_bindgen]
pub fn attach_telemetry(sink: Function) {
    TELEMETRY.with(|t| *t.borrow_mut() = Some(sink));
}

/// The domain capabilities this build can mount.
#[wasm_bindgen]
pub fn capabilities() -> Vec<String> {
    meridian_crew_services::platform::manifest_metadata::DOMAIN_CAPABILITIES
        .iter()
        .map(|c| c.to_string())
        .collect()
}

/// A TypeScript-shaped `Context` (as JSON) as an `MfeContext`.
fn context_from_json(json: &str) -> Result<MfeContext, JsValue> {
    let value: serde_json::Value = serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
    let mut context = MfeContext::new();
    let text = |key: &str| value.get(key).and_then(|v| v.as_str()).map(str::to_string);
    if let Some(id) = text("requestId") {
        context.request_id = id;
    }
    if let Some(inputs) = value.get("inputs").and_then(|v| v.as_object()) {
        context.inputs = inputs.clone();
    }
    // `capabilityId`, or the web lane's `inputs.component`.
    context.capability_id = text("capabilityId").or_else(|| context.inputs.get("component").and_then(|v| v.as_str()).map(str::to_string));
    context.jwt = text("jwt");
    if let Some(headers) = value.get("headers").and_then(|v| v.as_object()) {
        for (name, v) in headers {
            if let Some(v) = v.as_str() {
                context.headers.insert(name.clone(), v.to_string());
            }
        }
    }
    Ok(context)
}

fn json<T: serde::Serialize>(result: Result<T, MfeError>) -> Result<String, JsValue> {
    let value = result.map_err(to_js)?;
    serde_json::to_string(&value).map_err(|e| JsValue::from_str(&e.to_string()))
}

/// Run one of the ten capabilities by its contract name, with a
/// TypeScript-shaped context as JSON; answers the result as JSON.
#[wasm_bindgen]
pub async fn capability(name: String, context_json: String) -> Result<String, JsValue> {
    let mfe = mfe();
    let context = context_from_json(&context_json)?;
    match name.as_str() {
        "load" => json(mfe.load(context).await),
        "render" => json(mfe.render(context).await),
        "refresh" => json(mfe.refresh(context).await),
        "authorizeAccess" => json(mfe.authorize_access(context).await),
        "health" => json(mfe.health(context).await),
        "describe" => json(mfe.describe(context).await),
        "schema" => json(mfe.schema(context).await),
        "query" => json(mfe.query(context).await),
        "emit" => json(mfe.emit(context).await),
        "updateControlPlaneState" => json(mfe.update_control_plane_state(context).await),
        other => Err(JsValue::from_str(&format!("unknown capability \"{}\"", other))),
    }
}

/// Mount `capability` into `element` — what the remote entry's imperative
/// handle calls (ADR-056). `props_json` is the placement's props.
#[wasm_bindgen]
pub async fn mount(element: Element, capability: String, props_json: String) -> Result<(), JsValue> {
    let mfe = mfe();
    if matches!(mfe.state(), MfeLifecycleState::Uninitialized | MfeLifecycleState::Error) {
        mfe.load(MfeContext::new()).await.map_err(to_js)?;
    }
    mfe.render(MfeContext::new().with_capability_id(capability.clone()))
        .await
        .map_err(to_js)?;

    let props: serde_json::Value = serde_json::from_str(&props_json).unwrap_or(serde_json::Value::Null);
    draw(&capability, &element, &props)
}

/// Tear down what `mount` drew, and record the unmount.
#[wasm_bindgen]
pub fn unmount(element: Element, capability: String) {
    while let Some(child) = element.first_child() {
        let _ = element.remove_child(&child);
    }
    mfe().hooks().unmount(&capability);
}

/// Dispatch to the capability's developer-owned renderer.
fn draw(capability: &str, element: &Element, props: &serde_json::Value) -> Result<(), JsValue> {
    match capability {
        "CrewRoster" => crate::features::crew_roster::render(element, props),
        "PayStatus" => crate::features::pay_status::render(element, props),
        other => Err(JsValue::from_str(&format!("unknown capability \"{}\"", other))),
    }
}
